    /**
     * @param args the command line arguments
     */
    public static void main(String[] args) {
        Generador f=new Generador();
        f.setSize(800,450);
        f.setTitle("Practica 6: escaleras mecanicas");
        MiCanvas cv=new MiCanvas();
        f.add(cv);
        f.setVisible(true);
        int numHilos = 50;

        Semaphore semBajada = new Semaphore(4);
        Semaphore semTotal = new Semaphore(7);
        Semaphore semSubida = new Semaphore(4);

        Random r = new Random(System.currentTimeMillis());
        Thread[] hilos = new Thread[numHilos];//guardo todos los hilos para hacer el join al final

        for (int i = 0; i < numHilos; i++) {
            if (r.nextInt(100) < 50) {
                hilos[i] = new Thread(new Bajar(semBajada, semTotal, i, cv));
            } else {
                hilos[i] = new Subir(semSubida, semTotal, i, cv);
            }
            hilos[i].start();

            try {
                Thread.sleep(r.nextInt(1000, 2001));
            } catch (InterruptedException ex) {
            }
        }

        //espero a que terminen todos los clientes
        for (int i = 0; i < numHilos; i++) {
            try {
                hilos[i].join();
            } catch (InterruptedException ex) {
            }
        }

        System.out.println("Todos han terminado");
        try {
            Thread.sleep(3000);//espero 3 segundos para que se vea el estado final
        } catch (InterruptedException ex) {
        }
        System.exit(0);//cierro el programa
    }


